  "motivo_recusa": null,
  "fontes": [
    {
      "tipo": "norma",
      "id": "RESOLUÇÃO ANEEL N° 482/2012",
      "trecho_citado": "Art. 3º: O fornecedor de energia elétrica deve fornecer informações claras sobre a qualidade do serviço prestado, incluindo parâmetros técnicos e prazos de atendimento."
    }
  ],
  "confianca": "alta"
}

